class Solution {
public:
    string makeLargestSpecial(string s) {
        int count = 0, i = 0;
        vector<string> parts;
        for (int j = 0; j < (int)s.length(); j++) {
            count += (s[j] == '1') ? 1 : -1;
            if (count == 0) {
                parts.push_back("1" + makeLargestSpecial(s.substr(i + 1, j - i - 1)) + "0");
                i = j + 1;
            }
        }
        sort(parts.begin(), parts.end(), greater<string>());
        string res = "";
        for (const string& p : parts) res += p;
        return res;
    }
};

class Solution {
    public String makeLargestSpecial(String s) {
        int count = 0, i = 0;
        List<String> parts = new ArrayList<>();
        for (int j = 0; j < s.length(); j++) {
            count += (s.charAt(j) == '1') ? 1 : -1;
            if (count == 0) {
                parts.add("1" + makeLargestSpecial(s.substring(i + 1, j)) + "0");
                i = j + 1;
            }
        }
        parts.sort(Collections.reverseOrder());
        return String.join("", parts);
    }
}

var makeLargestSpecial = function(s) {
    let count = 0;
    let i = 0;
    const parts = [];
    for (let j = 0; j < s.length; j++) {
        count += (s[j] === '1') ? 1 : -1;
        if (count === 0) {
            parts.push('1' + makeLargestSpecial(s.substring(i + 1, j)) + '0');
            i = j + 1;
        }
    }
    parts.sort((a, b) => b.localeCompare(a));
    return parts.join('');
};
